mapper.select:
    	SELECT 
			COUNT(t.TASK_ID) AS TOTAL_COUNT
		FROM TASK t 
		WHERE 1=1
			AND PROJECT_ID = #{project_id}
			AND IS_ENABLE = #{is_enable}
			AND USER_ID = #{user_id}
			AND TITLE LIKE CONCAT('%',#{title},'%')
			AND CONTENTS LIKE CONCAT('%',#{contents},'%')
			AND LABEL_TYPE = #{label_type]}
		ORDER BY t.TASK_ID DESC

mapper.update:
UPDATE TASK t

		,t.BASE_TASK_ID = NULL

WHERE t.TASK_ID = #{task_id}
